    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        vm.deal(bob, 1 ether);
        vm.prank(bob);
        c.deposit{value: 1 ether}();

        vm.prank(alice);
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
